import json,urllib.request,hashlib,re,concurrent.futures
acc=[]
for n,l in enumerate(open("ob_accounts.txt"),1):
    p=[x.strip() for x in l.split("|")]
    if len(p)>=3 and p[1].startswith("sk-obs1"): acc.append((n,p[0],p[1]))
def info(a):
    n,num,k=a
    try:
        r=urllib.request.Request("https://obscurify.ai/get_user_balance",headers={"Authorization":f"Bearer {k}"})
        with urllib.request.urlopen(r,timeout=25) as x: b=json.load(x)['balance']
