        with urllib.request.urlopen(r2,timeout=25) as x: s=json.load(x)
        reqs=sum(p.get('requests',0) for p in s.get('periods',[]))
        spent=sum(float(p.get('spent',0) or 0) for p in s.get('periods',[]))
        return (b,reqs,spent,n,num)
    except Exception: return (9,0,0,n,num)
res=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=10) as ex:
    for r in ex.map(info,acc): res.append(r)
res=[r for r in res if r[0]!=9]
res.sort(key=lambda r:-r[1])
print(f"{'saldo':>6} {'request':>8} {'spent':>9}  akun")
